        TraversalResult result1 = cached.traverse(graph);
        System.out.println("Cache size: " + cached.getCacheSize());

        System.out.println("Second call - from cache...");
        TraversalResult result2 = cached.traverse(graph);
        System.out.println("Cache size: " + cached.getCacheSize());
